wire rstn;          // reset sincronizado (KEY[0], ativo em 0)
wire tick_1hz;      // pulso de 1 ciclo de clock a cada segundo
wire [6:0] count;   // segundos, de 00 a 99


//=======================================================
//  Structural coding
//=======================================================

// sincroniza o botao de reset com o clock de 50 MHz
AsyncInputSynchronizer sync (
     .clk(MAX10_CLK1_50),
     .asyncn(KEY[0]),
     .syncn(rstn)
);

// 50 MHz -> 1 pulso por segundo
divisor div (
     .clock_in(MAX10_CLK1_50),
     .reset_n(rstn),
     .enable(1'b1),
     .clock_out(tick_1hz)
);

// contador MOD 100, habilitado uma vez por segundo
counter cnt (
     .clk(MAX10_CLK1_50),
     .rstn(rstn),
     .en(tick_1hz),
     .count(count)
);

// unidade em HEX0 e dezena em HEX1
SEG7_LUT u_hex0 (
     .iDIG(count % 10),
     .oSEG(HEX0[6:0])
);

SEG7_LUT u_hex1 (
     .iDIG(count / 10),
     .oSEG(HEX1[6:0])
);

// ponto decimal e displays nao usados apagados
assign HEX0[7] = 1'b1;
assign HEX1[7] = 1'b1;
assign HEX2 = 8'hFF;
assign HEX3 = 8'hFF;
assign HEX4 = 8'hFF;
